/// Raven `AngleDifference`.
///
/// Source: `oracle/oracle/codemp/game/ai_main.c:425-436`
pub fn AngleDifference(
    ang1: f32,
    ang2: f32,
) -> f32 {
    // Raven: signed shortest-arc difference between two yaw angles.
    let mut diff = ang1 - ang2;
    if ang1 > ang2 {
        if diff > 180.0 {
            diff -= 360.0;
        }
    } else if diff < -180.0 {
        diff += 360.0;
    }
    diff
}

/// Raven `BotChangeViewAngle`.
///
/// Source: `oracle/oracle/codemp/game/ai_main.c:443-463`
pub fn BotChangeViewAngle(
    angle: f32,
    ideal_angle: f32,
    speed: f32,
) -> f32 {
    let angle = crate::q_math::AngleMod(angle);
    let ideal_angle = crate::q_math::AngleMod(ideal_angle);
    if angle == ideal_angle {
        return angle;
    }
    let mut mv = ideal_angle - angle;
    if ideal_angle > angle {
        if mv > 180.0 {
            mv -= 360.0;
        }
    } else if mv < -180.0 {
        mv += 360.0;
    }
    if mv > 0.0 {
        if mv > speed {
            mv = speed;
        }
    } else if mv < -speed {
        mv = -speed;
    }
    crate::q_math::AngleMod(angle + mv)
}

/// Raven `BotChangeViewAngles`.
///
/// `PITCH`/`YAW` indices are 0/1 (Raven `q_shared.h`); no ported const module
/// exports them, so the literal indices are used with a note.
///
/// Source: `oracle/oracle/codemp/game/ai_main.c:470-530`
pub fn BotChangeViewAngles(
    ctx: GameContext<'_>,
    bs: *mut bot_state_t,
    thinktime: f32,
) {
    const PITCH: usize = 0;
    unsafe {
        let bs = &mut *bs;
        if bs.ideal_viewangles[PITCH] > 180.0 {
            bs.ideal_viewangles[PITCH] -= 360.0;
        }

        let mut factor: f32;
        if !bs.currentEnemy.is_none() && bs.frame_Enemy_Vis != 0 {
            if bs.settings.skill <= 1.0 {
                factor = (bs.skills.turnspeed_combat * 0.4) * bs.settings.skill;
            } else if bs.settings.skill <= 2.0 {
                factor = (bs.skills.turnspeed_combat * 0.6) * bs.settings.skill;
            } else if bs.settings.skill <= 3.0 {
                factor = (bs.skills.turnspeed_combat * 0.8) * bs.settings.skill;
            } else {
                factor = bs.skills.turnspeed_combat * bs.settings.skill;
            }
        } else {
            factor = bs.skills.turnspeed;
        }

        if factor > 1.0 {
            factor = 1.0;
        }
        if factor < 0.001 {
            factor = 0.001;
        }

        let mut maxchange = bs.skills.maxturn;
        maxchange *= thinktime;
        for i in 0..2usize {
            bs.viewangles[i] = crate::q_math::AngleMod(bs.viewangles[i]);
            bs.ideal_viewangles[i] = crate::q_math::AngleMod(bs.ideal_viewangles[i]);
            let diff = AngleDifference(bs.viewangles[i], bs.ideal_viewangles[i]);
            let disired_speed = diff * factor;
            bs.viewanglespeed[i] += bs.viewanglespeed[i] - disired_speed;
            if bs.viewanglespeed[i] > 180.0 {
                bs.viewanglespeed[i] = maxchange;
            }
            if bs.viewanglespeed[i] < -180.0 {
                bs.viewanglespeed[i] = -maxchange;
            }
            let mut anglespeed = bs.viewanglespeed[i];
            if anglespeed > maxchange {
                anglespeed = maxchange;
            }
            if anglespeed < -maxchange {
                anglespeed = -maxchange;
            }
            bs.viewangles[i] += anglespeed;
            bs.viewangles[i] = crate::q_math::AngleMod(bs.viewangles[i]);
            bs.viewanglespeed[i] *= 0.45 * (1.0 - factor);
        }
        if bs.viewangles[PITCH] > 180.0 {
            bs.viewangles[PITCH] -= 360.0;
        }
        trap::EA_View(
            ctx.engine,
            BotlibEaViewArgs::new(bs.client, &bs.viewangles as *const vec3_t),
        );
    }
}

