/// Raven `CheckForFunc`.
///
/// Source: `oracle/oracle/codemp/game/ai_main.c:1053-1083`
pub fn CheckForFunc(
    ctx: GameContext<'_>,
    org: vec3_t,
    ignore: c_int,
) -> c_int {
    unsafe {
        let world = &*ctx.world;
        let mut under = org;
        under[2] -= 64.0;

        let mut tr: trace_t = core::mem::zeroed();
        trap::Trace(
            ctx.engine,
            GTraceArgs::new(
                &mut tr,
                &org,
                core::ptr::null(),
                core::ptr::null(),
                &under,
                ignore,
                MASK_SOLID,
            ),
        );

        if tr.fraction == 1.0 {
            return 0;
        }

        let fent = &world.entities[tr.entityNum as usize];
        // Raven `if (!fent)` on `&g_entities[...]` is structurally dead. Raven
        // then `strstr(fent->classname, ...)` and would deref a null classname
        // (UB); guarding null is the one defined behavior here.
        if !fent.classname.is_null() {
            let cn = core::ffi::CStr::from_ptr(fent.classname);
            if cn.to_bytes().windows(5).any(|w| w == b"func_") {
                return 1; // there's a func brush here
            }
        }
    }
    0
}

